-- 独立设计约束模型；不是 tender-app 的生产迁移。仅在全新隔离库执行。
BEGIN;
CREATE SCHEMA design;
SET search_path TO design, public;
CREATE DOMAIN sha256 AS text CHECK (VALUE ~ '^[0-9a-f]{64}$');
CREATE TABLE members (
  id uuid PRIMARY KEY, display_name text NOT NULL, active boolean NOT NULL DEFAULT true
);
CREATE TABLE bids (
  id uuid PRIMARY KEY, title text NOT NULL,
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  material_revision bigint NOT NULL DEFAULT 1 CHECK (material_revision > 0),
  settings_revision bigint NOT NULL DEFAULT 1 CHECK (settings_revision > 0),
  presentation_revision bigint NOT NULL DEFAULT 1 CHECK (presentation_revision > 0),
  settings jsonb NOT NULL CHECK (jsonb_typeof(settings) = 'object'),
  created_by uuid NOT NULL REFERENCES members(id), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE blobs (
  id uuid PRIMARY KEY, digest sha256 NOT NULL UNIQUE, object_key text NOT NULL UNIQUE,
  byte_size bigint NOT NULL CHECK (byte_size >= 0), media_type text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE document_versions (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL REFERENCES bids(id), blob_id uuid NOT NULL REFERENCES blobs(id),
  original_name text NOT NULL, obtained_at timestamptz NOT NULL,
  artifact_kind text NOT NULL CHECK (artifact_kind IN ('bid_body','review_report','annotated_review_copy','source_original','research_artifact')),
  created_by uuid NOT NULL REFERENCES members(id), created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (bid_id,id)
);
CREATE TABLE material_snapshots (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL REFERENCES bids(id), revision bigint NOT NULL CHECK (revision > 0),
  manifest jsonb NOT NULL CHECK (jsonb_typeof(manifest) = 'object'), digest sha256 NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(bid_id,revision), UNIQUE(bid_id,id)
);
CREATE TABLE material_assignments (
  snapshot_id uuid NOT NULL, bid_id uuid NOT NULL, document_version_id uuid NOT NULL,
  role text NOT NULL CHECK(role IN ('tender','supplement','drawing','boq','body','official_result','other')),
  ordinal integer NOT NULL CHECK(ordinal >= 0),
  PRIMARY KEY(snapshot_id,role,ordinal),
  FOREIGN KEY(bid_id,snapshot_id) REFERENCES material_snapshots(bid_id,id),
  FOREIGN KEY(bid_id,document_version_id) REFERENCES document_versions(bid_id,id)
);
CREATE TABLE drafts (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL REFERENCES bids(id), revision bigint NOT NULL CHECK(revision > 0),
  UNIQUE(bid_id,id)
);
CREATE TABLE sections (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, draft_id uuid NOT NULL,
  head_revision bigint NOT NULL CHECK(head_revision > 0), UNIQUE(bid_id,id), UNIQUE(bid_id,draft_id,id),
  FOREIGN KEY(bid_id,draft_id) REFERENCES drafts(bid_id,id)
);
CREATE TABLE section_revisions (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, draft_id uuid NOT NULL, section_id uuid NOT NULL, revision bigint NOT NULL CHECK(revision > 0),
  schema_digest sha256 NOT NULL, content jsonb NOT NULL CHECK(jsonb_typeof(content) = 'object'), digest sha256 NOT NULL,
  created_by uuid NOT NULL REFERENCES members(id), created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(bid_id,draft_id,section_id) REFERENCES sections(bid_id,draft_id,id),
  UNIQUE(section_id,revision), UNIQUE(bid_id,id), UNIQUE(bid_id,draft_id,id)
);
CREATE TABLE draft_snapshots (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, draft_id uuid NOT NULL, revision bigint NOT NULL CHECK(revision > 0),
  manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest) = 'object'), digest sha256 NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(bid_id,draft_id) REFERENCES drafts(bid_id,id),
  UNIQUE(draft_id,revision), UNIQUE(bid_id,id), UNIQUE(bid_id,draft_id,id)
);
CREATE TABLE draft_snapshot_sections (
  snapshot_id uuid NOT NULL, bid_id uuid NOT NULL, draft_id uuid NOT NULL, section_revision_id uuid NOT NULL, ordinal integer NOT NULL CHECK(ordinal >= 0),
  PRIMARY KEY(snapshot_id,ordinal), UNIQUE(snapshot_id,section_revision_id),
  FOREIGN KEY(bid_id,draft_id,snapshot_id) REFERENCES draft_snapshots(bid_id,draft_id,id),
  FOREIGN KEY(bid_id,draft_id,section_revision_id) REFERENCES section_revisions(bid_id,draft_id,id)
);
CREATE TABLE commands (
  id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES members(id), command_kind text NOT NULL,
  target_id uuid NOT NULL, idempotency_key text NOT NULL CHECK(length(idempotency_key) BETWEEN 1 AND 128),
  request_digest sha256 NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(actor_id,command_kind,target_id,idempotency_key)
);
CREATE TABLE operations (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL REFERENCES bids(id), command_id uuid NOT NULL REFERENCES commands(id),
  kind text NOT NULL, input_digest sha256 NOT NULL,
  state text NOT NULL CHECK(state IN ('queued','running','cancel_requested','succeeded','failed','cancelled')),
  handler_version text NOT NULL, cancel_requested_at timestamptz, finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(bid_id,id),
  CHECK((state IN ('succeeded','failed','cancelled')) = (finished_at IS NOT NULL)),
  CHECK(state NOT IN ('cancel_requested','cancelled') OR cancel_requested_at IS NOT NULL)
);
CREATE UNIQUE INDEX active_same_input ON operations(bid_id,kind,input_digest)
  WHERE state IN ('queued','running','cancel_requested');
CREATE TABLE step_receipts (
  operation_id uuid NOT NULL REFERENCES operations(id), step_key text NOT NULL, input_digest sha256 NOT NULL,
  fence bigint NOT NULL CHECK(fence > 0), attempt_count integer NOT NULL CHECK(attempt_count > 0),
  state text NOT NULL CHECK(state IN ('running','succeeded','failed','cancelled')),
  heartbeat_at timestamptz, output jsonb,
  PRIMARY KEY(operation_id,step_key,input_digest)
);
CREATE TABLE effect_receipts (
  operation_id uuid NOT NULL REFERENCES operations(id), effect_key text NOT NULL,
  result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(operation_id,effect_key)
);
CREATE TABLE review_inputs (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, material_snapshot_id uuid NOT NULL, body_version_id uuid NOT NULL,
  input_digest sha256 NOT NULL, method_digest sha256 NOT NULL, manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='object'),
  frozen_at timestamptz NOT NULL,
  FOREIGN KEY(bid_id,material_snapshot_id) REFERENCES material_snapshots(bid_id,id),
  FOREIGN KEY(bid_id,body_version_id) REFERENCES document_versions(bid_id,id), UNIQUE(bid_id,id)
);
CREATE TABLE review_runs (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, input_id uuid NOT NULL, operation_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(bid_id,id),
  FOREIGN KEY(bid_id,input_id) REFERENCES review_inputs(bid_id,id),
  FOREIGN KEY(bid_id,operation_id) REFERENCES operations(bid_id,id)
);
CREATE TABLE review_slots (
  bid_id uuid PRIMARY KEY REFERENCES bids(id), active_review_id uuid,
  pending_intent jsonb CHECK(pending_intent IS NULL OR jsonb_typeof(pending_intent) = 'object'),
  revision bigint NOT NULL CHECK(revision > 0),
  FOREIGN KEY(bid_id,active_review_id) REFERENCES review_runs(bid_id,id)
);
CREATE TABLE review_results (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, review_id uuid NOT NULL,
  core_coverage text NOT NULL CHECK(core_coverage IN ('complete','partial','failed')),
  payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(bid_id,review_id) REFERENCES review_runs(bid_id,id), UNIQUE(bid_id,id)
);
CREATE TABLE build_inputs (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, draft_snapshot_id uuid NOT NULL,
  template_digest sha256 NOT NULL, render_digest sha256 NOT NULL, manifest jsonb NOT NULL,
  FOREIGN KEY(bid_id,draft_snapshot_id) REFERENCES draft_snapshots(bid_id,id), UNIQUE(bid_id,id)
);
CREATE TABLE builds (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, input_id uuid NOT NULL, operation_id uuid NOT NULL,
  FOREIGN KEY(bid_id,input_id) REFERENCES build_inputs(bid_id,id),
  FOREIGN KEY(bid_id,operation_id) REFERENCES operations(bid_id,id), UNIQUE(bid_id,id)
);
CREATE TABLE build_outputs (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL, build_id uuid NOT NULL, format text NOT NULL CHECK(format IN ('docx','pdf')),
  document_version_id uuid, state text NOT NULL CHECK(state IN ('succeeded','failed')),
  gaps jsonb NOT NULL CHECK(jsonb_typeof(gaps) = 'array'),
  FOREIGN KEY(bid_id,build_id) REFERENCES builds(bid_id,id),
  FOREIGN KEY(bid_id,document_version_id) REFERENCES document_versions(bid_id,id),
  UNIQUE(build_id,format), CHECK((state='succeeded') = (document_version_id IS NOT NULL))
);
CREATE TABLE submission_records (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL REFERENCES bids(id), body_version_id uuid NOT NULL, review_id uuid,
  kind text NOT NULL CHECK(kind IN ('standard','offline_fact')), gate_snapshot jsonb,
  evidence jsonb NOT NULL, submitted_at timestamptz NOT NULL, created_by uuid NOT NULL REFERENCES members(id),
  supersedes_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(bid_id,id),
  FOREIGN KEY(bid_id,body_version_id) REFERENCES document_versions(bid_id,id),
  FOREIGN KEY(bid_id,review_id) REFERENCES review_runs(bid_id,id),
  FOREIGN KEY(bid_id,supersedes_id) REFERENCES submission_records(bid_id,id),
  CHECK(kind <> 'standard' OR (review_id IS NOT NULL AND gate_snapshot IS NOT NULL))
);
CREATE FUNCTION validate_standard_submission() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE reviewed_body uuid; selected_kind text;
BEGIN
  IF NEW.kind = 'standard' THEN
    SELECT i.body_version_id INTO reviewed_body
      FROM design.review_runs r JOIN design.review_inputs i ON i.bid_id=r.bid_id AND i.id=r.input_id
      WHERE r.bid_id=NEW.bid_id AND r.id=NEW.review_id;
    SELECT artifact_kind INTO selected_kind FROM design.document_versions WHERE bid_id=NEW.bid_id AND id=NEW.body_version_id;
    IF reviewed_body IS DISTINCT FROM NEW.body_version_id OR selected_kind IS DISTINCT FROM 'bid_body' THEN
      RAISE EXCEPTION 'submission_body_mismatch' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER submission_identity BEFORE INSERT ON submission_records
  FOR EACH ROW EXECUTE FUNCTION validate_standard_submission();
CREATE TABLE submission_heads (
  bid_id uuid PRIMARY KEY REFERENCES bids(id), submission_id uuid NOT NULL,
  revision bigint NOT NULL CHECK(revision > 0),
  FOREIGN KEY(bid_id,submission_id) REFERENCES submission_records(bid_id,id)
);
CREATE TABLE proposed_actions (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL REFERENCES bids(id), base_revision bigint NOT NULL CHECK(base_revision > 0),
  request_digest sha256 NOT NULL, expires_at timestamptz NOT NULL, payload jsonb NOT NULL
);
CREATE TABLE action_consumptions (
  action_id uuid PRIMARY KEY REFERENCES proposed_actions(id), command_id uuid NOT NULL REFERENCES commands(id),
  consumed_by uuid NOT NULL REFERENCES members(id), result jsonb NOT NULL, consumed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE outbox (
  id uuid PRIMARY KEY, operation_id uuid REFERENCES operations(id), topic text NOT NULL,
  deduplication_key text NOT NULL UNIQUE, payload jsonb NOT NULL,
  available_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, publish_attempts integer NOT NULL DEFAULT 0 CHECK(publish_attempts >= 0)
);
CREATE INDEX outbox_due ON outbox(available_at,id) WHERE published_at IS NULL;
CREATE TABLE stream_heads (
  id uuid PRIMARY KEY, bid_id uuid NOT NULL REFERENCES bids(id), last_seq bigint NOT NULL DEFAULT 0 CHECK(last_seq >= 0)
);
CREATE TABLE stream_events (
  stream_id uuid NOT NULL REFERENCES stream_heads(id), seq bigint NOT NULL CHECK(seq > 0),
  event_id uuid NOT NULL UNIQUE, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(stream_id,seq)
);
CREATE TABLE audit_entries (
  id uuid PRIMARY KEY, actor_id uuid REFERENCES members(id), bid_id uuid REFERENCES bids(id),
  command_id uuid REFERENCES commands(id), event_type text NOT NULL, payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'immutable_record' USING ERRCODE='55000'; END;
$$;
DO $$
DECLARE table_name text;
BEGIN
  FOREACH table_name IN ARRAY ARRAY['blobs','document_versions','material_snapshots','material_assignments',
    'section_revisions','draft_snapshots','draft_snapshot_sections','review_inputs','review_runs','review_results',
    'build_inputs','build_outputs','submission_records','effect_receipts','proposed_actions','action_consumptions','stream_events','audit_entries']
  LOOP
    EXECUTE format('CREATE TRIGGER immutable_guard BEFORE UPDATE OR DELETE ON design.%I FOR EACH ROW EXECUTE FUNCTION design.append_only()',table_name);
  END LOOP;
END;
$$;
-- TRUNCATE与DDL由数据库角色权限禁止；生产运行账号不得拥有表与schema。
COMMIT;

-- 全新系统领域DDL；先执行core.sql。design为目标原型schema，不连接旧系统。
BEGIN;
SET search_path TO design,public;
CREATE TABLE engineering_projects(id uuid PRIMARY KEY,title text NOT NULL,region text,engineering_type text);
CREATE TABLE bid_rounds(id uuid PRIMARY KEY,engineering_project_id uuid NOT NULL REFERENCES engineering_projects(id),lot text,round_no integer NOT NULL CHECK(round_no>0),UNIQUE(engineering_project_id,lot,round_no));
CREATE TABLE bidders(id uuid PRIMARY KEY,name text NOT NULL,company_facts jsonb NOT NULL DEFAULT '{}');
CREATE TABLE bid_profiles(
 bid_id uuid PRIMARY KEY REFERENCES bids(id),round_id uuid NOT NULL REFERENCES bid_rounds(id),bidder_id uuid NOT NULL REFERENCES bidders(id),
 phase text NOT NULL CHECK(phase IN ('preparation','working','submitted','closed','terminated')),archived_at timestamptz,deadline timestamptz,
 current_body_id uuid,current_material_id uuid,current_review_id uuid,current_draft_id uuid,
 FOREIGN KEY(bid_id,current_body_id) REFERENCES document_versions(bid_id,id),
 FOREIGN KEY(bid_id,current_material_id) REFERENCES material_snapshots(bid_id,id),
 FOREIGN KEY(bid_id,current_review_id) REFERENCES review_runs(bid_id,id),FOREIGN KEY(bid_id,current_draft_id) REFERENCES drafts(bid_id,id)
);
CREATE TABLE credentials(member_id uuid PRIMARY KEY REFERENCES members(id),login_name text NOT NULL UNIQUE,password_hash text NOT NULL,disabled_at timestamptz);
CREATE TABLE sessions(id uuid PRIMARY KEY,member_id uuid NOT NULL REFERENCES members(id),token_digest sha256 NOT NULL UNIQUE,csrf_digest sha256 NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE INDEX active_sessions ON sessions(member_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE upload_batches(id uuid PRIMARY KEY,bid_id uuid NOT NULL REFERENCES bids(id),revision bigint NOT NULL CHECK(revision>0),state text NOT NULL CHECK(state IN ('open','verifying','committed','failed')),created_by uuid NOT NULL REFERENCES members(id),UNIQUE(bid_id,id));
CREATE TABLE uploads(
 id uuid PRIMARY KEY,bid_id uuid NOT NULL,batch_id uuid NOT NULL,filename text NOT NULL,role text NOT NULL,
 declared_digest sha256 NOT NULL,declared_size bigint NOT NULL CHECK(declared_size>0),staging_key text NOT NULL UNIQUE,
 state text NOT NULL CHECK(state IN ('authorized','uploaded','verifying','verified','quarantined','expired')),expires_at timestamptz NOT NULL,
 verified_version_id uuid,error_code text,FOREIGN KEY(bid_id,batch_id) REFERENCES upload_batches(bid_id,id),
 FOREIGN KEY(bid_id,verified_version_id) REFERENCES document_versions(bid_id,id),UNIQUE(bid_id,id)
);
CREATE TABLE parse_runs(
 id uuid PRIMARY KEY,bid_id uuid NOT NULL,document_version_id uuid NOT NULL,parser_digest sha256 NOT NULL,config_digest sha256 NOT NULL,
 page_count integer NOT NULL CHECK(page_count>=0),coverage text NOT NULL CHECK(coverage IN ('complete','partial','failed')),
 gaps jsonb NOT NULL CHECK(jsonb_typeof(gaps)='array'),created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(bid_id,document_version_id) REFERENCES document_versions(bid_id,id),UNIQUE(bid_id,id),UNIQUE(bid_id,id,document_version_id)
);
CREATE TABLE pages(
 bid_id uuid NOT NULL,parse_id uuid NOT NULL,physical_page integer NOT NULL CHECK(physical_page>0),printed_label text,
 width numeric NOT NULL CHECK(width>0 AND width<>'NaN'),height numeric NOT NULL CHECK(height>0 AND height<>'NaN'),
 rotation integer NOT NULL CHECK(rotation IN (0,90,180,270)),quality text NOT NULL CHECK(quality IN ('usable','partial','failed')),gaps jsonb NOT NULL,
 PRIMARY KEY(parse_id,physical_page),UNIQUE(bid_id,parse_id,physical_page),FOREIGN KEY(bid_id,parse_id) REFERENCES parse_runs(bid_id,id)
);
CREATE TABLE evidence_blocks(
 id uuid PRIMARY KEY,bid_id uuid NOT NULL,parse_id uuid NOT NULL,physical_page integer NOT NULL,ordinal integer NOT NULL CHECK(ordinal>=0),
 kind text NOT NULL CHECK(kind IN ('text','table','visual_observation')),text_content text NOT NULL,bbox jsonb,structure jsonb,
 digest sha256 NOT NULL,UNIQUE(bid_id,id),UNIQUE(parse_id,physical_page,ordinal),
 FOREIGN KEY(bid_id,parse_id,physical_page) REFERENCES pages(bid_id,parse_id,physical_page)
);
CREATE TABLE rule_sets(id uuid PRIMARY KEY,bid_id uuid NOT NULL,material_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),digest sha256 NOT NULL,coverage text NOT NULL CHECK(coverage IN ('complete','partial','conflict')),FOREIGN KEY(bid_id,material_id) REFERENCES material_snapshots(bid_id,id),UNIQUE(bid_id,id));
ALTER TABLE bid_profiles ADD COLUMN current_rule_set_id uuid;
ALTER TABLE bid_profiles ADD CONSTRAINT current_rule_set_identity FOREIGN KEY(bid_id,current_rule_set_id) REFERENCES rule_sets(bid_id,id);
CREATE TABLE rule_items(
 id uuid PRIMARY KEY,bid_id uuid NOT NULL,rule_set_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('disqualification','mandatory','scoring','advisory')),
 statement text NOT NULL,conditions jsonb NOT NULL,exceptions jsonb NOT NULL,max_points numeric,
 evidence_ids uuid[] NOT NULL CHECK(cardinality(evidence_ids)>0),bands jsonb NOT NULL,
 CHECK(max_points IS NULL OR (max_points>0 AND max_points<>'NaN' AND max_points<>'Infinity')),
 FOREIGN KEY(bid_id,rule_set_id) REFERENCES rule_sets(bid_id,id),UNIQUE(bid_id,id)
);
ALTER TABLE rule_items ADD COLUMN applicability_scope jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(applicability_scope)='object');
ALTER TABLE rule_items ADD COLUMN origin_kind text NOT NULL DEFAULT 'model_extracted' CHECK(origin_kind IN ('model_extracted','human_added','carried_human'));
ALTER TABLE rule_items ADD COLUMN manual_origin_rule_id uuid;
ALTER TABLE rule_items ADD COLUMN provenance_status text NOT NULL DEFAULT 'effective' CHECK(provenance_status IN ('effective','needs_revalidation','superseded'));
ALTER TABLE rule_items ADD CONSTRAINT manual_rule_origin FOREIGN KEY(bid_id,manual_origin_rule_id) REFERENCES rule_items(bid_id,id);
ALTER TABLE rule_items ADD CONSTRAINT manual_rule_identity CHECK((origin_kind='model_extracted' AND manual_origin_rule_id IS NULL) OR (origin_kind='human_added' AND manual_origin_rule_id IS NOT NULL AND manual_origin_rule_id=id) OR (origin_kind='carried_human' AND manual_origin_rule_id IS NOT NULL));
CREATE TABLE fact_sets(id uuid PRIMARY KEY,bid_id uuid NOT NULL REFERENCES bids(id),digest sha256 NOT NULL,UNIQUE(bid_id,id));
CREATE TABLE fact_items(id uuid PRIMARY KEY,bid_id uuid NOT NULL,fact_set_id uuid NOT NULL,subject text NOT NULL,scope text NOT NULL,name text NOT NULL,value jsonb NOT NULL,unit text,evidence_ids uuid[] NOT NULL,FOREIGN KEY(bid_id,fact_set_id) REFERENCES fact_sets(bid_id,id),UNIQUE(bid_id,id));
CREATE TABLE decisions(
 id uuid PRIMARY KEY,bid_id uuid NOT NULL REFERENCES bids(id),object_kind text NOT NULL,object_id uuid NOT NULL,object_revision bigint NOT NULL,
 decision text NOT NULL,reason text NOT NULL,evidence_ids uuid[] NOT NULL,actor_id uuid NOT NULL REFERENCES members(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX decisions_current ON decisions(bid_id,object_kind,object_id,created_at DESC,id DESC);
CREATE TABLE findings(
 id uuid PRIMARY KEY,bid_id uuid NOT NULL,review_id uuid NOT NULL,rule_id uuid,
 category text NOT NULL CHECK(category IN ('disqualification','response','consistency','scope','improvement')),
 severity text NOT NULL CHECK(severity IN ('critical','major','minor','info')),
 verdict text NOT NULL CHECK(verdict IN ('satisfied','violated','not_found','unable_to_judge','not_applicable')),
 statement text NOT NULL,searched_ranges jsonb NOT NULL,evidence_ids uuid[] NOT NULL,carried_from_id uuid,
 FOREIGN KEY(bid_id,review_id) REFERENCES review_runs(bid_id,id),FOREIGN KEY(bid_id,rule_id) REFERENCES rule_items(bid_id,id),
 UNIQUE(bid_id,id),FOREIGN KEY(bid_id,carried_from_id) REFERENCES findings(bid_id,id)
);
CREATE INDEX findings_review ON findings(bid_id,review_id,severity,id);
CREATE TABLE template_versions(id uuid PRIMARY KEY,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('outline','layout')),schema_digest sha256 NOT NULL,config jsonb NOT NULL,fontset_digest sha256 NOT NULL);
CREATE TABLE writing_plans(id uuid PRIMARY KEY,bid_id uuid NOT NULL,section_id uuid NOT NULL,base_section_revision bigint NOT NULL,rule_ids uuid[] NOT NULL,fact_set_id uuid,source_version_ids uuid[] NOT NULL,plan jsonb NOT NULL,FOREIGN KEY(bid_id,section_id) REFERENCES sections(bid_id,id),FOREIGN KEY(bid_id,fact_set_id) REFERENCES fact_sets(bid_id,id));
CREATE TABLE conversations(id uuid PRIMARY KEY,bid_id uuid NOT NULL REFERENCES bids(id),state text NOT NULL CHECK(state IN ('active','closed','hidden')),revision bigint NOT NULL CHECK(revision>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(bid_id,id));
CREATE TABLE messages(id uuid PRIMARY KEY,bid_id uuid NOT NULL,conversation_id uuid NOT NULL,client_message_id uuid,role text NOT NULL CHECK(role IN ('user','assistant','tool')),parts jsonb NOT NULL CHECK(jsonb_typeof(parts)='array'),created_by uuid REFERENCES members(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(bid_id,conversation_id) REFERENCES conversations(bid_id,id),UNIQUE(conversation_id,client_message_id));
CREATE TABLE outcomes(
 id uuid PRIMARY KEY,bid_id uuid NOT NULL,submission_id uuid NOT NULL,score_kind text NOT NULL CHECK(score_kind IN ('technical_total','comprehensive_total','unknown')),
 value numeric,maximum numeric,source_version_id uuid NOT NULL,known_at timestamptz NOT NULL,supersedes_id uuid,created_by uuid NOT NULL REFERENCES members(id),
 CHECK((value IS NULL AND maximum IS NULL) OR (value IS NOT NULL AND maximum IS NOT NULL AND value>=0 AND value<>'NaN' AND value<>'Infinity' AND maximum>0 AND maximum<>'NaN' AND maximum<>'Infinity' AND value<=maximum)),
 FOREIGN KEY(bid_id,submission_id) REFERENCES submission_records(bid_id,id),FOREIGN KEY(bid_id,source_version_id) REFERENCES document_versions(bid_id,id),
 UNIQUE(bid_id,id),FOREIGN KEY(bid_id,supersedes_id) REFERENCES outcomes(bid_id,id)
);
CREATE TABLE outcome_heads(submission_id uuid PRIMARY KEY,bid_id uuid NOT NULL,outcome_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),FOREIGN KEY(bid_id,submission_id) REFERENCES submission_records(bid_id,id),FOREIGN KEY(bid_id,outcome_id) REFERENCES outcomes(bid_id,id));
CREATE TABLE task_definitions(id uuid PRIMARY KEY,bid_id uuid NOT NULL REFERENCES bids(id),revision bigint NOT NULL CHECK(revision>0),name text NOT NULL,purpose text NOT NULL CHECK(purpose IN ('assist','compliance','export')),instructions text NOT NULL,paused boolean NOT NULL DEFAULT false,UNIQUE(bid_id,id));
CREATE TABLE schedules(id uuid PRIMARY KEY,bid_id uuid NOT NULL,definition_id uuid NOT NULL,definition_revision bigint NOT NULL,cron text NOT NULL,timezone text NOT NULL,next_fire_at timestamptz NOT NULL,paused boolean NOT NULL DEFAULT false,FOREIGN KEY(bid_id,definition_id) REFERENCES task_definitions(bid_id,id));
CREATE TABLE schedule_receipts(schedule_id uuid NOT NULL REFERENCES schedules(id),scheduled_at timestamptz NOT NULL,operation_id uuid NOT NULL REFERENCES operations(id),PRIMARY KEY(schedule_id,scheduled_at));
